{
    CActionEventRemoveObject e;
    CCharString data;
    std::sprintf(data.Text, "RIGHT_HAND,X");
    e.Hand.Text[0] = 0;
    g_lastIndex = -1;
    g_parseResult = 7;
    bool ok = e.SetDataFromString(data);
    int pass = ok == true && g_lastIndex == 0 && e.Hand.Text[0] == 'R' && e.Hand.Text[10] == 0;
    g_parseResult = 0;
    bool bad = e.SetDataFromString(data);
    pass = pass && bad == false;
